#include <stdint.h>
#include "stm32f411xe.h"

void delay(volatile uint32_t count)
{
    while(count--) { __NOP(); }
}

volatile uint32_t brightness = 0;
volatile int8_t direction = 1;

int main(void)
{
    /* Enable FPU */
    SCB->CPACR |= ((3UL << 20) | (3UL << 22));

    // Enable GPIOA clock
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN;

    // PA5 -> Alternate function (TIM2_CH1)
    GPIOA->MODER &= ~(0x3 << (5 * 2));
    GPIOA->MODER |=  (0x2 << (5 * 2));  // AF mode
    GPIOA->AFR[0] &= ~(0xF << (5 * 4));
    GPIOA->AFR[0] |=  (0x1 << (5 * 4)); // AF1 = TIM2_CH1

    // Enable GPIOC clock
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOCEN;

    // Enable TIM2 clock
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN;

    // Timer setup
    TIM2->PSC = 84 - 1;   // 1 MHz
    TIM2->ARR = 4000 - 1; // 0-4000 duty
    TIM2->DIER |= TIM_DIER_UIE;   // Enable update interrupt

    NVIC_EnableIRQ(TIM2_IRQn);

    // PWM mode 1, preload enable
    TIM2->CCMR1 &= ~TIM_CCMR1_OC1M;
    TIM2->CCMR1 |= (6 << TIM_CCMR1_OC1M_Pos); // PWM1
    TIM2->CCMR1 |= TIM_CCMR1_OC1PE;

    TIM2->CCER |= TIM_CCER_CC1E; // Enable CH1 output
    TIM2->CR1 |= TIM_CR1_CEN;    // Start timer

    while(1)
    {
       //cpu je slobodan
    }
}

void TIM2_IRQHandler(void)
{
    if (TIM2->SR & TIM_SR_UIF)   // Update interrupt flag
    {
        TIM2->SR &= ~TIM_SR_UIF; // Clear flag

        brightness += direction * 10;

        if (brightness >= 1000)
        {
            brightness = 1000;
            direction = -1;
        }
        else if (brightness == 0)
        {
            direction = 1;
        }

        TIM2->CCR1 = brightness;
    }
}
